from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(1,'operations','Opérations et priorités','1 · Nombres et calculs',
'Décimaux · Parenthèses · Division · Calcul réfléchi',
['Choisir une opération et en estimer le résultat.','Diviser par un nombre décimal non nul.','Traduire un problème par une expression.'],
['Tables de multiplication et numération décimale.'],[
page(1,'Organiser les calculs',
bloc('definition',r'Une somme réunit des termes ; un produit réunit des facteurs. Dans $7+3\times4$, la dernière opération est une addition : l’expression est une somme. Dans $(7+3)\times4$, c’est un produit.'),
bloc('propriete',r'Calculer d’abord les parenthèses, puis les multiplications et divisions, enfin les additions et soustractions. À priorité égale, calculer de gauche à droite.'),
bloc('exemple',r'$18-6:3+2\times4=18-2+8=24$. Mais $(18-6):(3+2)\times4=12:5\times4=9{,}6$. Réécrire les parties inchangées à chaque étape.'),
bloc('savoirfaire',r'Avant de calculer, prévoir un ordre de grandeur. Pour $19{,}8\times5{,}1$, $20\times5=100$ est un contrôle utile. Une estimation ne remplace pas le résultat exact.','Anticiper et contrôler')),
page(2,'Diviser et calculer efficacement',
bloc('definition',r'Pour $b\ne0$, $a:b$ est le nombre qui, multiplié par $b$, donne $a$. Multiplier le dividende et le diviseur par un même nombre non nul conserve le quotient.'),
bloc('exemple',r'$7{,}56:0{,}6=75{,}6:6=12{,}6$. On transforme le diviseur en entier. Contrôle : $12{,}6\times0{,}6=7{,}56$. Diviser par $0{,}6$, qui est inférieur à 1, peut augmenter le nombre.'),
bloc('propriete',r'$k(a+b)=ka+kb$ et $k(a-b)=ka-kb$. La distributivité permet de développer ou de regrouper un calcul : $17\times99=17(100-1)=1700-17=1683$.'),
bloc('attention',r'Une division par zéro est impossible. Dans un problème, distinguer le nombre exact de parts et le nombre entier d’objets à acheter : $23:4=5{,}75$, mais il faut six boîtes de quatre places pour 23 objets.'))
],[
E('Addition décimale',r'Calculer $4{,}7+2{,}85$.',r'Aligner les rangs : $4{,}70+2{,}85=\res{7{,}55}$. Le total est proche de $5+3=8$.','Aligner les unités.','assert Rational("4.7")+Rational("2.85")==Rational("7.55")'),
E('Différence décimale',r'Calculer $10-3{,}48$.',r'$10{,}00-3{,}48=\res{6{,}52}$. Contrôle : $6{,}52+3{,}48=10$.','Vérifier par addition.','assert 10-Rational("3.48")==Rational("6.52")'),
E('Produit de décimaux',r'Calculer $0{,}8\times1{,}5$.',r'$8\times15=120$. Les deux facteurs ont ensemble deux chiffres après la virgule : le produit est $\res{1{,}20=1{,}2}$.','Utiliser les rangs décimaux.','assert Rational(".8")*Rational("1.5")==Rational("1.2")'),
E('Diviser par un décimal',r'Calculer $9{,}6:0{,}4$.',r'On multiplie les deux nombres par 10 : $96:4=\res{24}$. Contrôle : $24\times0{,}4=9{,}6$.','Rendre le diviseur entier.','assert Rational("9.6")/Rational(".4")==24'),
E('Nommer une expression',r'Dans $5+2\times7$ puis $(5+2)\times7$, quelle est la dernière opération ? Calculer.',r'Le premier calcul est une somme : $5+14=\res{19}$. Le second est un produit : $7\times7=\res{49}$.','Repérer la structure avant le calcul.','assert 5+2*7==19 and (5+2)*7==49'),
E('Même priorité',r'Calculer $36:6\times3$ et $24-8+5$.',r'De gauche à droite : $36:6\times3=6\times3=\res{18}$ et $24-8+5=16+5=\res{21}$.','Garder l’ordre à priorité égale.','assert Rational(36,6)*3==18 and 24-8+5==21'),
E('Deux étages de parenthèses',r'Calculer $42-[3\times(8-5)+7]$.',r'La parenthèse donne 3 ; le crochet vaut $3\times3+7=16$. Donc $42-16=\res{26}$.','Commencer à l’intérieur.','assert 42-(3*(8-5)+7)==26'),
E('Distribuer pour gagner du temps',r'Calculer $23\times101$ et $48\times9{,}5+48\times0{,}5$.',r'$23(100+1)=2300+23=\res{2323}$. On regroupe le second calcul : $48(9{,}5+0{,}5)=48\times10=\res{480}$.','Chercher une somme de facteurs simple.','assert 23*101==2323 and 48*Rational("9.5")+48*Rational(".5")==480'),
E('Une division à contrôler',r'Calculer $6{,}3:0{,}15$ puis contrôler le résultat.',r'$6{,}3:0{,}15=630:15=\res{42}$. Le contrôle donne $42\times0{,}15=6{,}3$.','Multiplier les deux nombres par 100.','assert Rational("6.3")/Rational(".15")==42'),
E('Corriger une priorité',r'Léo écrit $7+3\times5=10\times5=50$. Expliquer son erreur.',r'Il a additionné avant de multiplier, sans parenthèses. Il faut $7+15=\res{22}$. Le résultat 50 correspond à $(7+3)\times5$.','Conserver l’expression de départ.','assert 7+3*5==22 and (7+3)*5==50'),
E('Une sortie',r'Quatre élèves paient chacun 6,50 euros de transport et 3,20 euros d’entrée. Écrire une seule expression pour le total puis calculer.',r'Chaque élève paie $6{,}50+3{,}20=9{,}70$ euros. Le total est $4(6{,}50+3{,}20)=\res{38{,}80}$ euros. Distribuer donne aussi $26+12{,}80$.','Déterminer d’abord ce que paie une personne.','assert 4*(Rational("6.5")+Rational("3.2"))==Rational("38.8")'),
E('Des bouteilles',r'On verse 8,4 L dans des bouteilles de 0,75 L. Combien remplit-on de bouteilles entières ? Quel volume reste-t-il ?',r'$8{,}4:0{,}75=11{,}2$ : on remplit $\res{11}$ bouteilles. Elles contiennent $11\times0{,}75=8{,}25$ L ; il reste $\res{0{,}15\ \mathrm L}$. Une douzième bouteille n’est pas pleine.','Interpréter le quotient.','assert Rational("8.4")/Rational(".75")==Rational("11.2") and Rational("8.4")-11*Rational(".75")==Rational(".15")'),
E('Un budget partagé',r'Une association a 125 euros. Elle achète cinq lots à 12,40 euros et partage le reste également entre six ateliers. Quelle somme reçoit chaque atelier ?',r'Les achats coûtent $5\times12{,}40=62$ euros. Le reste est $125-62=63$ euros. Chaque atelier reçoit $(125-5\times12{,}40):6=\res{10{,}50}$ euros.','Distinguer dépense, reste et partage.','assert (125-5*Rational("12.4"))/6==Rational("10.5")'),
E('Une expression à inventer',r'Avec 8, 6 et 2 utilisés chacun une fois, proposer un calcul donnant 28. Justifier le rôle des parenthèses.',r'Une solution est $\res{(8+6)\times2=28}$. Sans parenthèses, $8+6\times2=20$. Les parenthèses imposent de calculer la somme avant le produit.','Chercher une étape intermédiaire.','assert (8+6)*2==28 and 8+6*2==20'),
E('Comparer deux offres',r'Un magasin vend un carnet 2,80 euros. Un autre vend un lot de cinq carnets 12 euros avec 1,50 euro de frais pour toute commande. Pour dix carnets, comparer les coûts.',r'Premier magasin : $10\times2{,}80=28$ euros. Second : $2\times12+1{,}50=25{,}50$ euros. Le second coûte $\res{2{,}50}$ euros de moins. Les frais sont ajoutés une seule fois.','Traduire chaque offre séparément.','assert 10*Rational("2.8")-(2*12+Rational("1.5"))==Rational("2.5")')
],reperes=['Opérations et ordres de grandeur','Division par un décimal','Priorités et vocabulaire','Distributivité numérique et problèmes'],deco='calcul')

chapitre(2,'divisibilite','Multiples, diviseurs et partages','1 · Nombres et calculs',
'Division euclidienne · Critères · Recherche organisée',
['Utiliser quotient et reste.','Reconnaître des multiples et des diviseurs.','Organiser une recherche de solutions entières.'],['Tables et calcul posé.'],[
page(1,'Comprendre la division entière',
bloc('definition',r'Pour des entiers $a\ge0$ et $b>0$, la division euclidienne donne $a=bq+r$, avec $q$ entier et $0\le r<b$. $q$ est le quotient, $r$ le reste.'),
bloc('exemple',r'$83=7\times11+6$. On fait 11 paquets de sept et il reste six objets. Si tous les objets doivent être transportés dans des boîtes de sept, il faut douze boîtes.'),
bloc('definition',r'$a$ est un multiple de $b$ si $a=bq$ pour un entier $q$. Pour $b>0$, cela signifie que $b$ divise $a$ et que le reste de la division est nul. Ainsi 36 est multiple de 9, et 9 est un diviseur de 36.'),
bloc('savoirfaire',r'Chercher les diviseurs par paires : $24=1\times24=2\times12=3\times8=4\times6$. La liste complète est $1,2,3,4,6,8,12,24$.','Ne rien oublier')),
page(2,'Critères et recherches',
bloc('propriete',r'Un entier est divisible par 2 si son chiffre des unités est pair ; par 5 s’il finit par 0 ou 5 ; par 10 s’il finit par 0. Il est divisible par 3, respectivement par 9, si la somme de ses chiffres est divisible par 3, respectivement par 9.'),
bloc('exemple',r'Pour 234, $2+3+4=9$ : il est divisible par 3 et par 9. Il est pair, mais ne finit ni par 0 ni par 5.'),
bloc('savoirfaire',r'Pour former des lots identiques sans reste, le nombre de lots doit diviser chacun des effectifs. Lister les diviseurs puis garder ceux qui conviennent à toutes les contraintes. Pour des rendez-vous périodiques, comparer les listes de multiples.','Relier les contraintes'),
bloc('definition',r'Prolongement facultatif : un nombre premier a exactement deux diviseurs positifs, 1 et lui-même. 2, 3, 5 et 7 sont premiers ; 1 ne l’est pas. Le crible consiste à barrer les multiples des nombres premiers déjà trouvés.'))
],[
E('Quotient et reste',r'Effectuer la division euclidienne de 67 par 8.',r'$8\times8=64$ et $67-64=3$. Donc $\res{67=8\times8+3}$, avec $0\le3<8$.','Encadrer par deux multiples.','assert divmod(67,8)==(8,3)'),
E('Diviseur ou multiple',r'Compléter : 54 est un … de 6 ; 6 est un … de 54. Justifier.',r'$54=6\times9$. 54 est un $\res{multiple}$ de 6 et 6 un $\res{diviseur}$ de 54.','Écrire un produit entier.','assert 54==6*9'),
E('Tester 450',r'450 est-il divisible par 2, 3, 5, 9 et 10 ?',r'Il finit par 0 : divisibilité par 2, 5 et 10. La somme des chiffres vaut 9 : divisibilité par 3 et 9. Les cinq réponses sont $\res{oui}$.','Choisir le bon critère.','assert all(450%d==0 for d in [2,3,5,9,10])'),
E('Lister des diviseurs',r'Donner les diviseurs positifs de 18.',r'Les paires sont $1\times18$, $2\times9$, $3\times6$. La liste est $\res{1,2,3,6,9,18}$.','Former des paires de facteurs.','assert divisors(18)==[1,2,3,6,9,18]'),
E('Valider une écriture',r'$59=6\times8+11$ décrit-il la division euclidienne de 59 par 6 ?',r'Non : le reste 11 est supérieur au diviseur 6. Il faut $\res{59=6\times9+5}$ ; cette fois $0\le5<6$.','Contrôler aussi la taille du reste.','assert 59==6*8+11 and divmod(59,6)==(9,5)'),
E('Un chiffre manquant',r'Trouver tous les chiffres $a$ tels que le nombre $23a$ soit divisible par 3.',r'La somme des chiffres est $5+a$. Elle peut valoir 6, 9 ou 12 : $\res{a=1,4,7}$. On retrouve 231, 234 et 237.','Tester les dix chiffres avec le critère.','assert [a for a in range(10) if (230+a)%3==0]==[1,4,7]'),
E('Deux critères ensemble',r'Trouver le chiffre $a$ pour que $7a5$ soit divisible par 9. Est-il aussi divisible par 5 ?',r'$7+a+5=12+a$ doit être multiple de 9 : seul 18 convient, donc $\res{a=6}$. Le nombre 765 finit par 5 : il est aussi divisible par 5.','Croiser les critères.','assert [a for a in range(10) if (705+10*a)%9==0]==[6] and 765%5==0'),
E('Diviseurs communs',r'Lister les diviseurs communs à 24 et 36.',r'Diviseurs de 24 : $1,2,3,4,6,8,12,24$. Ceux qui divisent aussi 36 sont $\res{1,2,3,4,6,12}$.','Filtrer une première liste.','assert [d for d in divisors(24) if 36%d==0]==[1,2,3,4,6,12]'),
E('Premier multiple commun',r'Quel est le plus petit entier strictement positif multiple de 6 et de 8 ?',r'Multiples de 6 : $6,12,18,24,\ldots$ ; de 8 : $8,16,24,\ldots$. Le premier commun est $\res{24}$.','Comparer les listes de multiples.','assert ilcm(6,8)==24'),
E('Un crible limité',r'Prolongement : trouver les nombres premiers inférieurs à 20.',r'On retire 1, puis les multiples de 2 et de 3 autres que 2 et 3. Les nombres restants sont $\res{2,3,5,7,11,13,17,19}$. Les nombres composés de cet intervalle ont un facteur 2 ou 3.','Barrer les multiples organisés.','assert [a for a in range(2,20) if isprime(a)]==[2,3,5,7,11,13,17,19]'),
E('Transporter une classe',r'On transporte 137 personnes dans des minibus de neuf places. Combien faut-il de minibus ? Combien de places resteront libres ?',r'$137=9\times15+2$. Quinze minibus ne suffisent pas : il en faut $\res{16}$. Ils offrent 144 places, donc $\res7$ places libres.','Arrondir dans le sens du besoin.','assert divmod(137,9)==(15,2) and 16*9-137==7'),
E('Des bouquets identiques',r'On a 42 tulipes et 56 roses. On veut des bouquets identiques sans reste, au moins trois bouquets. Donner tous les nombres de bouquets possibles et la composition du plus grand nombre.',r'Les diviseurs communs sont $1,2,7,14$. Au moins trois bouquets impose $\res{7\text{ ou }14}$. Avec 14 bouquets : $\res3$ tulipes et $\res4$ roses chacun.','Écrire la contrainte de divisibilité.','assert [d for d in divisors(42) if 56%d==0 and d>=3]==[7,14] and 42//14==3 and 56//14==4'),
E('Deux signaux',r'Un signal se déclenche toutes les 12 minutes et un autre toutes les 18 minutes. Ils sonnent ensemble à 9 h. Quand sonneront-ils ensemble pour la première fois ensuite ?',r'Les premiers multiples communs apparaissent à 36 minutes : $3\times12=2\times18=36$. Le prochain déclenchement commun est à $\res{9\ \mathrm h\ 36}$.','Chercher un multiple commun minimal.','assert ilcm(12,18)==36'),
E('Un nombre à retrouver',r'Un entier entre 40 et 60 laisse un reste de 2 quand on le divise par 7 et est divisible par 3. Le trouver.',r'Les entiers de la forme $7q+2$ dans cet intervalle sont 44, 51 et 58. Seul $\res{51}$ est divisible par 3. Contrôle : $51=7\times7+2$.','Appliquer les contraintes successivement.','assert [a for a in range(40,61) if a%7==2 and a%3==0]==[51]'),
E('Une affirmation générale',r'Mila dit : « La somme de deux multiples de 4 est encore un multiple de 4. » Expliquer avec des paquets, puis vérifier sur 28 et 44.',r'Chaque nombre est formé de paquets de quatre ; réunir les deux collections donne encore des paquets de quatre. Ici $28+44=\res{72=4\times18}$. L’argument des paquets vaut pour tous les multiples, au-delà de cet exemple.','Expliquer ce qui reste vrai pour tous les cas.','assert 28+44==4*18 and expand(4*x+4*n)==4*(x+n)')
],reperes=['Division euclidienne et reste','Multiples, diviseurs et critères','Recherche organisée de solutions','Partages et phénomènes périodiques'],deco='calcul')

chapitre(3,'relatifs','Découvrir les nombres relatifs','1 · Nombres et calculs',
'Zéro · Opposé · Valeur absolue · Ordre',
['Lire et placer des nombres sur une droite.','Comparer des décimaux relatifs.','Distinguer signe et distance à zéro.'],['Repérage et nombres décimaux.'],[
page(1,'De part et d’autre de zéro',
bloc('definition',r'Les nombres relatifs permettent de représenter des valeurs inférieures à zéro. $-4$ peut être une température de quatre degrés sous zéro. Un nombre positif est supérieur ou égal à 0 ; un nombre strictement positif est supérieur à 0. De même, négatif signifie inférieur ou égal à 0, strictement négatif signifie inférieur à 0. Zéro est à la fois positif et négatif.'),
bloc('definition',r'Deux nombres sont opposés lorsque leur somme est nulle : $-3$ et $3$ sont opposés car $(-3)+3=0$. Sur une droite graduée, ils sont à la même distance de zéro, de part et d’autre. L’opposé de $a$ se note $-a$ ; ainsi $-(-3)=3$ : $-a$ n’est pas toujours négatif. La valeur absolue d’un nombre est sa distance à zéro : $-3$ et $3$ ont tous deux pour valeur absolue 3. La notation $\lvert a\rvert$ n’est pas exigible en Cinquième.'),
r'@FIG:cours-relatifs@',
bloc('attention',r'Le signe placé devant le nombre fait partie de son écriture. Sur une droite, l’unité de graduation doit rester constante.')),
page(2,'Comparer et ranger',
bloc('propriete',r'Sur une droite orientée vers la droite, les nombres augmentent de gauche à droite. Tout nombre strictement négatif est inférieur à 0 et à tout nombre positif. Entre deux nombres négatifs, celui qui est le plus loin de zéro est le plus petit.'),
bloc('exemple',r'$-7<-2$, alors que $-7$ est plus loin de zéro que $-2$ : sa valeur absolue est plus grande. Pour les décimaux, $-2{,}8<-2{,}35$ : $-2{,}8$ est plus loin de zéro que $-2{,}35$.'),
bloc('savoirfaire',r'Ranger d’abord les nombres négatifs, puis zéro, puis les positifs. Entre deux nombres, on peut toujours trouver un décimal : entre $-1{,}4$ et $-1{,}3$, on peut choisir $-1{,}35$.','Construire un ordre'),
bloc('savoirfaire',r'Indiquer la référence : niveau de la mer, température de fusion de l’eau, origine d’un axe. Le signe seul n’indique pas une distance parcourue.','Interpréter le signe'))
],[
E('Lire une graduation',r'Lire les abscisses de A, B et C sur la droite.',r'Chaque intervalle vaut une unité. On lit $\res{A(-3),\ B(1),\ C(4)}$. Le signe dépend du côté de zéro.','Identifier l’unité et l’origine.','assert [-3,1,4]==[-3,1,4]',figure='rel-1'),
E('Placer deux nombres',r'Placer $D(-2)$ et $E(3)$ sur la droite donnée.',r'D se place deux unités à gauche de 0 ; E trois unités à droite. Les positions sont ajoutées en vert.','Compter à partir de zéro.','assert -2<0<3',figure='rel-2'),
E('Trouver les opposés',r'Donner les opposés de $-8$, $2{,}4$ et 0.',r'Ils sont $\res8$, $\res{-2{,}4}$ et $\res0$. Zéro est son propre opposé.','Conserver la distance à zéro.','assert -(-8)==8 and -Rational("2.4")==Rational("-2.4") and -0==0'),
E('Distances à zéro',r'Sur une droite graduée, à quelle distance de zéro sont les points d’abscisses $-6{,}5$ et 4 ? En déduire la valeur absolue de chacun de ces nombres.',r'Le premier point est à $\res{6{,}5}$ unités de zéro, le second à $\res4$ unités. Ce sont les valeurs absolues de $-6{,}5$ et de 4 : une distance est positive ou nulle.','Lire une distance à zéro.','assert Abs(Rational("-6.5"))==Rational("6.5") and Abs(4)==4'),
E('Un premier ordre',r'Comparer $-5$ et 2, puis $-9$ et $-4$.',r'Un négatif est inférieur à un positif : $\res{-5<2}$. Parmi les négatifs, $-9$ est plus à gauche : $\res{-9<-4}$.','Utiliser la droite orientée.','assert -5<2 and -9<-4'),
E('Ranger des décimaux',r'Ranger dans l’ordre croissant, puis dans l’ordre décroissant : $1{,}2$ ; $-1{,}02$ ; 0 ; $-1{,}2$ ; $0{,}8$.',r'Les négatifs viennent d’abord ; $-1{,}2<-1{,}02$. Ordre croissant : $\res{-1{,}2<-1{,}02<0<0{,}8<1{,}2}$. Ordre décroissant : $\res{1{,}2>0{,}8>0>-1{,}02>-1{,}2}$.','Séparer les signes puis comparer.','L=[Rational(v) for v in ["1.2","-1.02","0","-1.2","0.8"]]\nassert sorted(L)==[Rational("-1.2"),Rational("-1.02"),0,Rational(".8"),Rational("1.2")] and sorted(L,reverse=True)==[Rational("1.2"),Rational(".8"),0,Rational("-1.02"),Rational("-1.2")]'),
E('Encadrer un négatif',r'Encadrer $-3{,}7$ entre deux entiers consécutifs.',r'Il est à gauche de $-3$ mais à droite de $-4$ : $\res{-4<-3{,}7<-3}$.','Lire l’ordre, pas seulement les chiffres.','assert -4<Rational("-3.7")<-3'),
E('Affiner une graduation',r'Lire les abscisses de F et G. Une unité est partagée en quatre.',r'Chaque petit intervalle vaut $1/4=0{,}25$. Les points sont $\res{F(-0{,}75)}$ et $\res{G(1{,}5)}$.','Déterminer la valeur d’un pas.','assert Rational(-3,4)==Rational("-.75") and Rational(6,4)==Rational("1.5")',figure='rel-8'),
E('Zéro et les signes',r'Parmi $-2$, 0 et 5, lister les nombres positifs, puis strictement positifs.',r'Les nombres positifs sont $\res{0\text{ et }5}$. Le seul strictement positif est $\res5$. Le mot « strictement » exclut zéro.','Appliquer les définitions exactes.','assert [a for a in [-2,0,5] if a>=0]==[0,5] and [a for a in [-2,0,5] if a>0]==[5]'),
E('Même distance',r'Sur une droite graduée, quels nombres sont situés à 4 unités de zéro ? Et à 0 unité de zéro ?',r'À quatre unités de zéro : $\res{-4\text{ et }4}$, deux nombres opposés. À distance nulle : $\res0$ seulement.','Chercher des deux côtés de zéro.','assert Abs(-4)==Abs(4)==4 and -4+4==0 and Abs(0)==0'),
E('Comparer des altitudes',r'Quatre lieux ont pour altitudes $-25$ m, 12 m, $-8$ m et 0 m. Les ranger du plus bas au plus haut et identifier ceux sous le niveau de la mer.',r'L’ordre est $\res{-25<-8<0<12}$. Les deux premiers sont sous le niveau de la mer ; 0 m est au niveau de référence.','Identifier le sens du classement.','assert sorted([-25,12,-8,0])==[-25,-8,0,12]'),
E('Trouver un intermédiaire',r'Proposer deux décimaux distincts strictement compris entre $-2{,}4$ et $-2{,}3$.',r'Par exemple $\res{-2{,}38\text{ et }-2{,}35}$. On vérifie $-2{,}4<-2{,}38<-2{,}35<-2{,}3$. Les bornes ne sont pas admises.','Ajouter un rang décimal.','assert Rational("-2.4")<Rational("-2.38")<Rational("-2.35")<Rational("-2.3")'),
E('Des contraintes entières',r'Lister les entiers $x$ vérifiant $-3<x\le2$.',r'On exclut $-3$ et on inclut 2 : $\res{-2,-1,0,1,2}$. Les signes $<$ et $\le$ n’imposent pas la même chose.','Lire chaque borne.','assert [a for a in range(-5,6) if -3<a<=2]==[-2,-1,0,1,2]'),
E('Une fausse règle',r'« Le nombre le plus éloigné de zéro est toujours le plus grand. » Donner un contre-exemple.',r'$-8$ est à 8 unités de zéro et 3 à seulement 3 unités, pourtant $\res{-8<3}$. La distance à zéro, c’est-à-dire la valeur absolue, ne suffit pas pour comparer : il faut aussi tenir compte du signe.','Choisir deux signes différents.','assert Abs(-8)>Abs(3) and -8<3'),
E('Classement et opposés',r'On sait que $-6<a<-2$. Sans connaître $a$, encadrer son opposé $-a$. Le nombre $-a$ est-il négatif ? Expliquer avec une droite.',r'Les positions possibles de $a$ sont entre $-6$ et $-2$. Leurs symétriques par rapport à zéro sont entre 2 et 6 : $\res{2<-a<6}$. Ici, $-a$ est donc $\res{positif}$ : l’écriture $-a$ ne désigne pas toujours un nombre négatif.','Réfléchir l’intervalle autour de zéro.','assert all(2<-a<6 and -a>0 for a in [Rational(-11,2),-5,-4,-3,Rational(-5,2)])',figure='rel-15')
],reperes=['Droite graduée et références','Opposé et valeur absolue','Comparaison et encadrements','Signe et interprétation'],deco='calcul')

chapitre(4,'sommes-relatifs','Additionner et soustraire des relatifs','1 · Nombres et calculs',
'Déplacements · Opposés · Sommes algébriques',
['Additionner des décimaux relatifs.','Transformer une soustraction en addition.','Interpréter une différence et une variation.'],['Ordre, opposés et valeur absolue.'],[
page(1,'Construire l’addition',
bloc('propriete',r'Pour additionner deux nombres de même signe, additionner les distances à zéro et garder le signe commun. S’ils sont de signes contraires, soustraire la plus petite distance à la plus grande et garder le signe du nombre le plus éloigné de zéro. Deux opposés ont pour somme 0.'),
r'@FIG:cours-addition@',
bloc('exemple',r'$(-4)+(-3)=-7$ ; $(-8)+5=-3$ ; $(-2)+7=5$. Sur une droite, ajouter un positif déplace vers la droite ; ajouter un négatif vers la gauche.'),
bloc('savoirfaire',r'On peut changer l’ordre des termes et les regrouper dans une addition : $-7+4+7-2=(-7+7)+(4-2)=2$.','Regrouper pour simplifier')),
page(2,'Soustraire et écrire clairement',
bloc('propriete',r'Soustraire un nombre revient à ajouter son opposé : $a-b=a+(-b)$. Ainsi $3-(-5)=3+5=8$, tandis que $3-5=3+(-5)=-2$.'),
bloc('savoirfaire',r'$(-4)+(+6)-(-2)=-4+6+2=4$. On supprime les parenthèses en tenant compte de l’opération qui les précède. Dans $8-(3-5)$, calculer d’abord la parenthèse ou changer les deux signes : $8-3+5=10$.','Simplifier sans perdre un signe'),
bloc('exemple',r'Une température passe de $-6$ à 2 degrés. Sa variation est valeur finale moins valeur initiale : $2-(-6)=8$ degrés. La température finale et la hausse sont deux quantités différentes.'),
bloc('attention',r'Une différence n’est pas une distance automatiquement positive : $-2-5=-7$. La distance entre les points d’abscisses $-2$ et 5 vaut 7. Le contexte indique ce qu’il faut calculer.'))
],[
E('Même signe positif',r'Calculer $3+8$.',r'Les termes sont positifs : $3+8=\res{11}$.','Additionner les distances à zéro.','assert 3+8==11'),
E('Même signe négatif',r'Calculer $(-4)+(-9)$.',r'On additionne 4 et 9 puis on garde le signe négatif : $\res{-13}$.','Conserver le signe commun.','assert -4-9==-13'),
E('Signes contraires',r'Calculer $-12+7$.',r'12 est la plus grande distance ; son signe est négatif. $12-7=5$, donc $\res{-5}$.','Comparer les distances à zéro.','assert -12+7==-5'),
E('Soustraire un négatif',r'Calculer $6-(-8)$.',r'Soustraire $-8$ revient à ajouter son opposé 8 : $6+8=\res{14}$.','Ajouter l’opposé.','assert 6-(-8)==14'),
E('Deux opposés',r'Calculer $-3{,}7+3{,}7$.',r'Les deux nombres sont opposés : leur somme vaut $\res0$.','Repérer les opposés.','assert -Rational("3.7")+Rational("3.7")==0'),
E('Deux décimaux',r'Calculer $-2{,}8+4{,}15$ et $-1{,}6-2{,}9$.',r'$4{,}15-2{,}80=\res{1{,}35}$. Le second calcul vaut $-1{,}6+(-2{,}9)=\res{-4{,}5}$.','Séparer signe et calcul décimal.','assert Rational("-2.8")+Rational("4.15")==Rational("1.35") and Rational("-1.6")-Rational("2.9")==Rational("-4.5")'),
E('Réorganiser une somme',r'Calculer $-17+6+17-4-6$.',r'On regroupe $-17+17=0$ et $6-6=0$. Il reste $\res{-4}$.','Chercher les paires d’opposés.','assert -17+6+17-4-6==-4'),
E('Parenthèses utiles',r'Calculer $5-(-2+7)$ puis $5-(-2)+7$.',r'Dans le premier : $-2+7=5$, donc $5-5=\res0$. Dans le second : $5+2+7=\res{14}$. Les parenthèses changent ce qu’on soustrait.','Identifier l’objet de la soustraction.','assert 5-(-2+7)==0 and 5-(-2)+7==14'),
E('Écrire plus simplement',r'Simplifier puis calculer $(-8)-(-3)+(+6)-(+4)$.',r'On obtient $-8+3+6-4$. Les positifs totalisent 9, les négatifs $-12$ ; le résultat vaut $\res{-3}$.','Transformer chaque soustraction.','assert (-8)-(-3)+6-4==-3'),
E('Une erreur de signe',r'Inès écrit $-5-(-9)=-14$. Corriger et vérifier.',r'Il faut $-5+9=\res4$. Vérification par l’addition inverse : $4+(-9)=-5$. Le résultat $-14$ correspondrait à $-5+(-9)$.','Contrôler par l’opération inverse.','assert -5-(-9)==4 and 4-9==-5'),
E('Températures',r'Il fait $-4{,}5\,^\circ$C le matin. La température monte de 7 degrés puis baisse de 3,2 degrés. Quelle est la température finale ?',r'On additionne les variations : $-4{,}5+7-3{,}2=\res{-0{,}7\,^\circ\mathrm C}$. Le passage par $2{,}5$ degrés permet de contrôler chaque étape.','Suivre les variations dans l’ordre.','assert Rational("-4.5")+7-Rational("3.2")==Rational("-.7")'),
E('Un ascenseur',r'Un ascenseur part de l’étage $-3$, monte de huit niveaux, descend de six puis monte de deux. Où arrive-t-il ? Quelle est sa variation totale ?',r'Il arrive à $-3+8-6+2=\res1$. Sa variation totale est $8-6+2=\res4$ niveaux vers le haut. Contrôle : $-3+4=1$.','Distinguer position et déplacement.','assert -3+8-6+2==1 and 8-6+2==4'),
E('Distance sur une droite',r'A et B ont pour abscisses $-6{,}5$ et $2{,}25$. Calculer la distance AB.',r'B est à droite de A. La distance vaut $2{,}25-(-6{,}5)=2{,}25+6{,}5=\res{8{,}75}$ unités. Elle est positive.','Faire valeur de droite moins valeur de gauche.','assert Rational("2.25")-Rational("-6.5")==Rational("8.75")',figure='add-13'),
E('Retrouver une variation',r'Un compte fictif passe de $-18{,}40$ euros à 7,25 euros après une seule opération. Quelle opération a eu lieu ?',r'La variation vaut $7{,}25-(-18{,}40)=\res{25{,}65}$ euros. Il s’agit d’un apport de cette somme, car la variation est positive.','Soustraire la valeur initiale à la finale.','assert Rational("7.25")-Rational("-18.40")==Rational("25.65")'),
E('Un bilan à reconstituer',r'Un jeu commence avec un score inconnu. On perd 12 points, on gagne 7 puis on perd 9. Le score final est $-6$. Retrouver le score initial.',r'On remonte les actions : avant la dernière perte, le score était $-6+9=3$ ; avant le gain, $3-7=-4$ ; au départ, $-4+12=\res8$. Contrôle : $8-12+7-9=-6$.','Remonter les opérations en sens inverse.','assert -6+9-7+12==8 and 8-12+7-9==-6')
],reperes=['Addition de relatifs','Soustraction et opposé','Parenthèses et sommes algébriques','Variations, distances et problèmes'],deco='calcul')
